import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faSpinner, faXmark } from "@fortawesome/free-solid-svg-icons";
import { default as cx } from "classnames";
import React, { memo, useCallback, useEffect, useMemo, useRef } from "react";
import { useSpring, animated, config, AnimatedComponent } from "@react-spring/web";
import "./SideDrawer.scss";
import { useAppStateStore } from "../../../store/appStateStore";
import useOverflowIndicators from "../../../hooks/useOverflowIndicators";

const AnimatedDivPure = memo(animated.div) as AnimatedComponent<"div">;

type Props = {
  children?: React.ReactNode,
  title?: string | React.ReactNode,
  closeDisabled?: boolean | "because loading",
  className?: string
  visibleBackdrop?: boolean
}

export default function SideDrawer({children, title, closeDisabled, className, visibleBackdrop = true}: Props) {
  const ref = useRef<HTMLDivElement>(null);
  const bodyRef = useRef<HTMLDivElement>(null);
  const overlayRef = useRef<HTMLDivElement>(null);

  const { showSettings, showGuideOverlay, leftHandedUi, set: setAppSetting } = useAppStateStore();

  const [sidebarWidth, setSidebarWidth] = React.useState(window.innerWidth);
  useEffect(() => {
    const width = ref?.current?.clientWidth
    if (width) {
      setSidebarWidth(width)
    }
    const handleResize = () => {
      if (ref?.current?.clientWidth) {
        setSidebarWidth(ref.current.clientWidth)
      }
    }
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, [])
  useEffect(() => {
    if (x.get() / sidebarWidth > 0.5) {
      open({immediate: true});
    } else {
      close();
    }
  }, [sidebarWidth]);

  const [{ x }, api] = useSpring(() => ({
    from: {
      x: 0, // Ideally this would be `showSettings ? sidebarWidth : 0` but we don't have a precise value for
        // sidebarWidth on first render so we start closed and then open immediately if needed when sidebarWidth is set
        // with a precise value
    },
    config: {
      mass: 0.3,
      tension: 600,
      friction: 26
    }
  }));

  const showSettingsFirstTimeRef = useRef(true);
  useEffect(() => {
    if (showSettings) {
      open({immediate: showSettingsFirstTimeRef.current})
    } else {
      close({immediate: showGuideOverlay});
    }
    showSettingsFirstTimeRef.current = false;
  }, [showSettings, showGuideOverlay]);

  const open = ({ canceled, immediate }: { canceled?: boolean, immediate?: boolean } = { canceled: false, immediate: false }) => {
    api.start({
      x: sidebarWidth,
      immediate,
      // when cancel is true, it means that the user passed the drag right threshold
      // so we change the spring config to create a nice wobbly effect
      config: canceled ? {
        mass: 0.9,
        tension: 400,
        friction: 20
      } : undefined,
      onRest: () => setAppSetting("showSettings", true)
    })
  }

  const close = useCallback(({ immediate }: { immediate?: boolean } = { immediate: false }) => {
    if (closeDisabled) {
      open();
      return;
    }
    api.start({
      x: 0,
      immediate,
      config: { ...config.stiff },
      onRest: () => setAppSetting("showSettings", false)
    })
  }, [api, closeDisabled]);


  const overlayOpacity = x.to((px) => visibleBackdrop ? 0.2 * (px / sidebarWidth) : 0)
  const overlayDisplay = x.to((px) => px > 0 ? 'block' : 'none')

  let closeButton = null;
  if (closeDisabled === "because loading") {
    closeButton = (
      <FontAwesomeIcon className="action" icon={faSpinner} pulse />
    );
  } else if (!closeDisabled) {
    closeButton = (
      <button
        className="action"
        data-testid="SideDrawer--closeButton"
        onClick={() => setAppSetting("showSettings", false)}
        type="button"
      >
        <FontAwesomeIcon icon={faXmark} />
        <span className="sr-only">Close settings</span>
      </button>
    );
  }

  const bodyScrollClasses = useOverflowIndicators(bodyRef);

  /* -------------------------------- Component ------------------------------- */

  return <>
    <AnimatedDivPure
      className={cx("settings-overlay")}
      style={useMemo(() => ({ display: overlayDisplay, opacity: overlayOpacity }), [overlayDisplay, overlayOpacity])}
      onClick={useCallback(() => close(), [])}
      ref={overlayRef}
    />
    <AnimatedDivPure
      className={cx("SideDrawer", className, { 'left-handed': leftHandedUi })}
      data-testid="SideDrawer"
      ref={ref}
      style={useMemo(() => ({ [leftHandedUi ? 'right' : 'left']: x.to(px => `calc(100% - ${px}px - var(--fixed-right-padding, 0px))`) }), [x, leftHandedUi])}
    >
      <div className="content">
        <div className={cx("body", bodyScrollClasses)} ref={bodyRef}>
          {children}
        </div>

        <div className="footer">
          <h2>{title}</h2>
          {closeButton}
        </div>
      </div>
    </AnimatedDivPure>
  </>;
};
